<script setup>import {onMounted,ref} from 'vue';import {api} from '../api';const now=new Date(),today=now.toISOString().slice(0,10),from=ref(today),to=ref(today),year=ref(now.getFullYear()),data=ref({monthly:[]});async function load(){data.value=(await api.get('/module-reports/expenses',{params:{from:from.value,to:to.value,year:year.value}})).data;}function money(v){return Number(v||0).toFixed(2)}onMounted(load);</script>
<template><h1>Expense Report</h1><div class="toolbar"><label>From<input type="date" v-model="from"></label><label>To<input type="date" v-model="to"></label><label>Trend Year<input type="number" v-model.number="year"></label><button @click="load">Apply</button></div><div class="grid"><div class="card"><div class="muted">Daily Expenses</div><div class="metric">₹{{money(data.dailyExpenses)}}</div></div><div class="card"><div class="muted">Salary Payments</div><div class="metric">₹{{money(data.salaryPayments)}}</div></div><div class="card"><div class="muted">Pharmacy Payments</div><div class="metric">₹{{money(data.pharmacyPayments)}}</div></div><div class="card"><div class="muted">Lab Payments</div><div class="metric">₹{{money(data.labPayments)}}</div></div><div class="card"><div class="muted">Doctor Payments</div><div class="metric">₹{{money(data.doctorPayments)}}</div></div><div class="card"><div class="muted">Total Cash Expenses</div><div class="metric">₹{{money(data.totalExpenses)}}</div></div></div><div class="card" style="margin-top:18px"><h2>Month-wise Expense</h2><table class="table"><tr><th>Month</th><th>Total Expense</th><th>Difference vs Previous Month</th></tr><tr v-for="x in data.monthly||[]" :key="x.month"><td>{{x.monthName}}</td><td><b>₹{{money(x.amount)}}</b></td><td :class="Number(x.differenceFromPreviousMonth)<=0?'positive-text':'danger'">{{Number(x.differenceFromPreviousMonth)>=0?'+':''}}₹{{money(x.differenceFromPreviousMonth)}}</td></tr></table></div></template>
